-- Migration: Question generation — AUD batch 14 (30 questions)
-- Date: 2026-02-23
-- Topic: Misstatements and Control Deficiencies
-- Difficulty: 9E / 15M / 6H
-- Bloom's: L1:8 / L2:9 / L3:8 / L4:5

BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L3 — Effect of misstatements near materiality threshold on further procedures
(1, 'Misstatements and Control Deficiencies', 'During the audit of Granite Valley Manufacturing, the engagement team identifies $38,000 in uncorrected misstatements when overall materiality is set at $45,000. What is the most likely effect of this proximity to the materiality threshold on the auditor''s planned procedures?', '["The auditor should perform additional procedures to determine whether additional undetected misstatements exist", "The auditor should reduce the scope of remaining procedures since materiality has not been exceeded", "The auditor should immediately issue a qualified opinion for the potential misstatement", "The auditor should increase materiality to accommodate the misstatements already found"]'::jsonb, 0, 'Under AU-C 450.11, when aggregate uncorrected misstatements approach materiality, the auditor must consider whether undetected misstatements combined with known misstatements could exceed materiality. This requires performing additional procedures to reduce that risk. Choice B is incorrect because reducing scope would be inappropriate—proximity to the threshold heightens the risk of undetected misstatements and demands more, not less, audit effort.', 'medium', 3),

-- Q2: medium / L2 — Calculating clearly trivial threshold
(1, 'Misstatements and Control Deficiencies', 'Redwood Financial Group sets overall materiality at $120,000 for the audit of Cascade Distribution Corp. The engagement partner establishes a clearly trivial threshold at 5% of overall materiality. A misstatement of $5,800 is identified during testing. Under AU-C 450, how should the auditor treat this misstatement?', '["Accumulate the misstatement because it exceeds the clearly trivial threshold", "Disregard the misstatement because it falls below the clearly trivial threshold", "Report the misstatement directly to those charged with governance", "Treat the misstatement as presumed material until management corrects it"]'::jsonb, 1, 'Under AU-C 450.05, the auditor need not accumulate misstatements that are clearly trivial. With materiality at $120,000, the clearly trivial threshold is $6,000 (5% x $120,000). Because $5,800 falls below this threshold, the auditor may disregard it. Choice A is incorrect because the misstatement does not exceed the $6,000 threshold—it falls below it, making accumulation unnecessary.', 'medium', 2),

-- Q3: easy / L1 — Definition of "clearly trivial" misstatements
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, which best describes the term ''clearly trivial'' as applied to misstatements?', '["Misstatements that individually fall below overall materiality", "Misstatements that are not expected to recur in subsequent periods", "Misstatements of an amount clearly inconsequential whether taken individually or in aggregate", "Misstatements that management has agreed to correct before year-end"]'::jsonb, 2, 'Under AU-C 450.A2, ''clearly trivial'' describes misstatements that are inconsequential both individually and in the aggregate—a threshold well below materiality. The auditor need not accumulate such items. Choice A is incorrect because a misstatement can be below materiality yet still not be clearly trivial; the standard contemplates a much lower threshold than materiality itself.', 'easy', 1),

-- Q4: easy / L1 — Three categories of misstatements per AU-C 450
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, which three categories are used to classify misstatements identified during an audit?', '["Known misstatements, estimated misstatements, and immaterial misstatements", "Quantitative misstatements, qualitative misstatements, and disclosure misstatements", "Systematic misstatements, random misstatements, and intentional misstatements", "Factual misstatements, judgmental misstatements, and projected misstatements"]'::jsonb, 3, 'AU-C 450.A1 classifies misstatements into three categories: factual (no doubt about existence), judgmental (differences in estimates or accounting policies), and projected (extrapolated from audit sample results to the population). Choice A is incorrect because ''estimated'' and ''immaterial'' are not standard classification categories—AU-C 450 uses precise terminology to distinguish the nature and source of each misstatement.', 'easy', 1),

-- Q5: easy / L1 — Timing of communication for material weaknesses
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, when must the auditor communicate material weaknesses in writing to those charged with governance?', '["Within 30 calendar days of the report release date", "Before the entity files its annual financial statements", "Immediately upon identification during fieldwork", "No later than 60 days after the report release date"]'::jsonb, 3, 'AU-C 265.13 requires the auditor to communicate identified significant deficiencies and material weaknesses in writing to those charged with governance no later than 60 days following the report release date. Choice C is incorrect because while timely communication is encouraged, the standard does not mandate immediate written communication upon identification—it allows up to 60 days after report release.', 'easy', 1),

-- Q6: easy / L1 — Content of summary of uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, the summary of uncorrected misstatements that the auditor requests management to correct should include:', '["All misstatements accumulated during the audit, other than those that are clearly trivial", "Only misstatements that individually exceed performance materiality", "Only factual misstatements confirmed by third-party evidence", "Only misstatements that affect the income statement"]'::jsonb, 0, 'Under AU-C 450.06-.07, the auditor accumulates all misstatements identified during the audit, except those that are clearly trivial, and communicates them to management requesting correction. Choice B is incorrect because the summary includes all accumulated misstatements regardless of whether they individually exceed performance materiality—projected and judgmental misstatements below performance materiality are also included.', 'easy', 1),

-- Q7: medium / L3 — Effect of a pervasive misstatement on the audit opinion
(1, 'Misstatements and Control Deficiencies', 'During the audit of Silverline Retail Corp., the engagement team discovers a $320,000 revenue recognition error affecting multiple product lines, customer segments, and reporting periods. Overall materiality is $250,000. If management refuses to correct this misstatement, what is the most likely effect on the audit opinion?', '["The auditor should issue a qualified opinion because the misstatement is material", "The auditor should issue an adverse opinion because the misstatement is both material and pervasive", "The auditor should withdraw from the engagement because the misstatement indicates fraud", "The auditor should issue a disclaimer of opinion due to a scope limitation"]'::jsonb, 1, 'Under AU-C 705.08, when a misstatement is both material (exceeding $250,000 materiality) and pervasive (affecting multiple product lines, segments, and periods), an adverse opinion is required. The pervasiveness elevates this beyond a qualified opinion. Choice A is incorrect because a qualified opinion applies only when misstatements are material but not pervasive—the multi-line, multi-period impact here makes the effect pervasive.', 'medium', 3),

-- Q8: easy / L2 — Identifying a deficiency from a scenario
(1, 'Misstatements and Control Deficiencies', 'Birchwood Enterprises assigns a single accounting clerk to initiate purchase orders, receive goods, and approve vendor invoices. Under AU-C 265, this arrangement most likely represents:', '["An inherent risk factor that increases the likelihood of fraud", "A compensating control that offsets segregation-of-duties weaknesses", "A control deficiency resulting from inadequate segregation of duties", "An acceptable practice for small entities with limited staff"]'::jsonb, 2, 'Under AU-C 265.A1, a control deficiency exists when a control is designed, implemented, or operated such that misstatements may not be prevented or detected on a timely basis. Combining initiation, custody, and approval functions in one person eliminates segregation of duties. Choice D is incorrect because while small entities may face resource constraints, AU-C 265 still requires the auditor to evaluate and communicate such deficiencies regardless of entity size.', 'easy', 2),

-- Q9: medium / L3 — Analysis of whether a control deficiency affects risk assessment
(1, 'Misstatements and Control Deficiencies', 'While auditing Pinnacle Software Inc., the auditor discovers that automated reconciliation controls over subscription revenue failed for six weeks due to a software patch error. During this period, $4.2 million in transactions were processed without reconciliation. What is the most likely effect of this deficiency on the auditor''s risk assessment?', '["The auditor should decrease detection risk because the control deficiency is temporary", "The auditor should maintain the original risk assessment since management corrected the error", "The auditor should increase overall materiality to reflect the additional uncertainty", "The auditor should increase the assessed risk of material misstatement for the affected revenue assertions"]'::jsonb, 3, 'Under AU-C 315.32, when the auditor identifies that a control did not operate effectively, the assessed risk of material misstatement for related assertions must be revised upward. The six-week gap over $4.2 million directly increases the risk that revenue could be misstated. Choice A is incorrect because a temporary failure does not reduce detection risk—it increases the assessed risk of material misstatement, requiring more substantive testing.', 'medium', 3),

-- Q10: medium / L2 — Applying tolerable misstatement to a sample finding
(1, 'Misstatements and Control Deficiencies', 'During the audit of Northstar Logistics LLC, the auditor tests a sample of 60 shipping invoices from a population of 3,600 and finds overcharges totaling $12,000. Performance materiality is $75,000. The projected misstatement to the population is $720,000. Under AU-C 530, the auditor should:', '["Conclude the misstatement likely exceeds tolerable misstatement and expand testing or request correction", "Accept the population as fairly stated because the sample misstatement is below performance materiality", "Disregard the projected misstatement because the actual errors found were immaterial", "Report only the $12,000 in known misstatements to those charged with governance"]'::jsonb, 0, 'Under AU-C 530.13-.14, when a projected misstatement ($720,000) exceeds tolerable misstatement derived from performance materiality ($75,000), the auditor must conclude the sample provides evidence of material misstatement. Additional procedures or management correction is needed. Choice B is incorrect because the relevant comparison is the projected misstatement ($720,000) to tolerable misstatement, not the sample error ($12,000) to performance materiality.', 'medium', 2),

-- Q11: medium / L2 — Requesting management written representations about uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'At the conclusion of the audit of Clearwater Energy Corp., the auditor identifies $18,000 in uncorrected misstatements that management declines to adjust. Overall materiality is $200,000. Under AU-C 580, the auditor should:', '["Withdraw the summary of uncorrected misstatements from the audit documentation", "Obtain a written representation from management that the effects of uncorrected misstatements are immaterial to the financial statements", "Adjust the financial statements without management''s consent to eliminate the misstatements", "Issue a qualified opinion solely because management refused to make corrections"]'::jsonb, 1, 'Under AU-C 580.15, the auditor must obtain a written representation from management acknowledging that the effects of uncorrected misstatements are, individually and in aggregate, immaterial to the financial statements. This ensures management takes responsibility for not correcting. Choice D is incorrect because a qualified opinion is not required when uncorrected misstatements ($18,000) are below materiality ($200,000) and management provides the required representation.', 'medium', 2),

-- Q12: medium / L2 — Prior period uncorrected misstatements affecting current year
(1, 'Misstatements and Control Deficiencies', 'During the audit of Ashford Consulting Group, the auditor notes that $45,000 in uncorrected misstatements from the prior year have reversed in the current year income statement but created a $45,000 overstatement of retained earnings on the balance sheet. Current-year materiality is $60,000. Under AU-C 450, the auditor should:', '["Disregard the prior-year misstatement because it has reversed in the current income statement", "Include the $45,000 balance sheet effect when evaluating aggregate uncorrected misstatements for the current year", "Require management to restate the prior-year financial statements before issuing the current-year opinion", "Report the prior-year misstatement as a subsequent event in the current-year audit report"]'::jsonb, 1, 'Under AU-C 450.10, the auditor evaluates the effect of uncorrected misstatements from prior periods on the current-period financial statements. Even though the income statement effect reversed, the $45,000 balance sheet overstatement persists and must be included in the aggregate assessment. Choice A is incorrect because AU-C 450 requires consideration of the cumulative balance sheet effect, not just the current-year income statement impact.', 'medium', 2),

-- Q13: hard / L4 — Evaluating competing considerations for material weakness classification
(1, 'Misstatements and Control Deficiencies', 'During the audit of Meridian Healthcare Systems, the auditor identifies that the revenue cycle lacks an independent reconciliation of patient billing charges to clinical services delivered. Over the past three years, no billing errors were detected through other procedures. However, the revenue cycle processes $85 million annually with a complex payer mix including Medicare, Medicaid, and commercial insurers. The engagement partner must determine whether this deficiency constitutes a material weakness. Which factor should most influence the evaluation?', '["The absence of historical billing errors over three years demonstrates the control''s unnecessary nature", "The presence of other detective controls that have prevented errors from reaching the financial statements", "The magnitude of transactions processed through the deficient control and the complexity of the payer environment", "The cost-benefit analysis of implementing the reconciliation compared to the risk of misstatement"]'::jsonb, 2, 'Under AU-C 265.A12, the severity of a control deficiency depends on the magnitude of the potential misstatement and the likelihood it could occur—not solely on historical error rates. With $85 million flowing through a complex payer mix, the potential misstatement is significant. Choice A is incorrect because the absence of detected errors does not prove the control is unnecessary; undetected misstatements may exist precisely because the reconciliation control is missing.', 'hard', 4),

-- Q14: medium / L2 — Known vs. likely misstatements in government audits
(1, 'Misstatements and Control Deficiencies', 'While conducting a GAGAS audit of the City of Brookhaven''s federal grant expenditures, the auditor tests a sample of 40 transactions totaling $160,000 from a population of $3.2 million and finds $8,000 in questioned costs. Under GAGAS and the Uniform Guidance, the auditor should report:', '["Only the $8,000 in known questioned costs because projections are not permitted under GAGAS", "The $8,000 as a finding without projecting to the population because the sample is too small", "A projected amount only if the known questioned costs exceed the materiality threshold", "Both the $8,000 in known questioned costs and the projected amount extrapolated to the $3.2 million population"]'::jsonb, 3, 'Under GAGAS and 2 CFR 200.516(a)(3), when questioned costs are identified in a sample, the auditor must report both the known questioned costs ($8,000) and the likely questioned costs projected to the full population. This ensures the federal grantor understands the full potential scope. Choice A is incorrect because GAGAS and the Uniform Guidance explicitly require projection of sample results to the population for compliance audit findings.', 'medium', 2),

-- Q15: medium / L3 — Analyzing the effect of an IT control deficiency on financial statement assertions
(1, 'Misstatements and Control Deficiencies', 'During the audit of Trident Manufacturing Corp., the auditor discovers that access controls over the enterprise resource planning system allow warehouse staff to modify inventory quantities and unit costs without supervisory approval. Which financial statement assertion is most likely affected by this control deficiency?', '["Presentation and disclosure, because inventory footnotes may omit material information", "Rights and obligations, because ownership of inventory may not be properly established", "Completeness, because inventory items may be omitted from the records", "Valuation, because unauthorized changes to quantities and unit costs can directly misstate inventory balances"]'::jsonb, 3, 'Under AU-C 315.A69, IT access control deficiencies affect the assertions related to the data that can be manipulated. When warehouse staff can modify both quantities and unit costs without approval, the valuation assertion is most directly at risk. Choice C is incorrect because the deficiency involves modifying existing records rather than omitting transactions—completeness risk would arise from the ability to delete, not alter, records.', 'medium', 3),

-- Q16: medium / L3 — Distinguishing between a control deficiency and a compliance finding
(1, 'Misstatements and Control Deficiencies', 'During the single audit of Lakeshore Community Health Center, the auditor identifies that the center did not verify participant eligibility for 15 of 50 sampled enrollments in a federal nutrition program. The center''s policies require eligibility verification before enrollment. What is the most likely effect on the auditor''s reporting?', '["The auditor should report both a compliance finding under the Uniform Guidance and evaluate whether the deficiency constitutes a significant deficiency or material weakness in internal control over compliance", "The auditor should report only a compliance finding because eligibility verification is a programmatic requirement, not an internal control matter", "The auditor should report only an internal control deficiency because the error rate does not exceed the compliance deviation threshold", "The auditor should report the finding to the federal grantor without classifying it as either a compliance or control issue"]'::jsonb, 0, 'Under GAGAS and 2 CFR 200.516(a), the auditor must report both the compliance violation (failure to verify eligibility) and the related internal control deficiency when the entity''s own policies were not followed. The 30% error rate (15/50) suggests at minimum a significant deficiency. Choice B is incorrect because internal control over compliance and compliance itself are distinct dimensions—failure to follow verification procedures is an internal control matter even though it also constitutes noncompliance.', 'medium', 3),

-- Q17: medium / L2 — Communicating other control deficiencies to management
(1, 'Misstatements and Control Deficiencies', 'After completing the audit of Westbrook Pharmaceuticals Inc., the auditor identifies several control deficiencies that do not individually or in combination rise to the level of significant deficiencies. Under AU-C 265, the auditor should:', '["Include these deficiencies in the written communication of significant deficiencies to those charged with governance", "Consider whether to communicate these deficiencies to management in writing or orally", "Document the deficiencies in the audit file but refrain from any communication to the entity", "Disclose the deficiencies in the auditor''s report on internal control"]'::jsonb, 1, 'Under AU-C 265.12, for control deficiencies that are not significant deficiencies or material weaknesses, the auditor should consider whether to communicate them to management. This communication may be written or oral and is distinct from the required written communication of significant deficiencies. Choice C is incorrect because AU-C 265 encourages the auditor to communicate even lesser deficiencies to management rather than merely documenting them without notification.', 'medium', 2),

-- Q18: hard / L4 — Evaluating whether to modify opinion when management acknowledges but won't correct
(1, 'Misstatements and Control Deficiencies', 'During the audit of Harborview Capital Partners, the auditor identifies $165,000 in uncorrected misstatements arising from management''s refusal to write down an impaired investment. Overall materiality is $200,000 and performance materiality is $150,000. Management acknowledges the misstatement but argues the investment will recover. The auditor has obtained sufficient evidence that impairment is other-than-temporary. Given that the misstatement is below overall materiality but exceeds performance materiality, the auditor should:', '["Accept the financial statements as presented because the misstatement is below overall materiality", "Issue a disclaimer of opinion because the disagreement with management creates a scope limitation", "Evaluate whether the uncorrected misstatement, combined with other misstatements and qualitative factors, is material to the financial statements before determining the opinion", "Require management to obtain a third-party valuation before the auditor can issue any opinion"]'::jsonb, 2, 'Under AU-C 450.11 and AU-C 705.07, the auditor must evaluate both quantitative and qualitative factors when aggregate uncorrected misstatements approach materiality. At $165,000 versus $200,000 materiality, quantitative proximity combined with qualitative factors such as management bias may render the misstatement material. Choice A is incorrect because a misstatement below overall materiality can still be material when qualitative considerations—such as management''s bias in resisting an evidence-supported impairment—are weighed.', 'hard', 4),

-- Q19: hard / L4 — Evaluating remediation under PCAOB standards
(1, 'Misstatements and Control Deficiencies', 'While performing an integrated audit of Apex Global Industries under PCAOB standards, the engagement team identifies a material weakness in the company''s financial close process. Management implemented a remediation plan two weeks before year-end that includes hiring additional staff and redesigning the close checklist. The newly hired staff completed one monthly close cycle before the balance sheet date. Under PCAOB AS 2201, the auditor should:', '["Accept that the material weakness has been remediated because management implemented corrective actions before year-end", "Issue an unqualified opinion on internal control because the remediation plan is reasonable and partially implemented", "Conclude that the material weakness has not been remediated because the new controls have not operated for a sufficient period to test their operating effectiveness", "Defer the integrated audit until the remediation has been in place for at least one full quarter"]'::jsonb, 2, 'Under PCAOB AS 2201.98, a material weakness exists as of the assessment date if the remediated controls have not operated long enough for the auditor to obtain sufficient evidence of operating effectiveness. Two weeks with one close cycle is insufficient. Choice A is incorrect because implementation alone does not remediate a material weakness—the auditor must test that new controls operate effectively over a reasonable period, not merely verify their existence.', 'hard', 4),

-- Q20: hard / L3 — Analyzing interaction between fraud risk and control deficiency classification
(1, 'Misstatements and Control Deficiencies', 'During the audit of Sterling Construction Corp., the auditor discovers that the controller has been overriding journal entry approval controls to reclassify costs between projects. The override shifted $95,000 in cost overruns from a fixed-price contract to a cost-plus contract, inflating the cost-plus project''s billable costs. Overall materiality is $500,000. The auditor should classify this finding as:', '["A material weakness, because the deficiency involves management override combined with fraud risk indicators regardless of the dollar amount relative to materiality", "A significant deficiency, because the $95,000 misstatement is well below the $500,000 overall materiality", "A control deficiency requiring oral communication to management but not escalation to those charged with governance", "A compliance violation that falls outside the scope of the financial statement audit"]'::jsonb, 0, 'Under AU-C 265.A13 and AU-C 240.32, a control deficiency involving management override with indicators of intentional misstatement elevates the severity assessment regardless of dollar amount. Management override to misallocate costs suggests fraud risk, which constitutes a material weakness. Choice B is incorrect because severity assessment for deficiencies involving fraud risk considers the nature of the deficiency—intentional override to misstate billings—not merely the quantitative amount relative to materiality.', 'hard', 3),

-- Q21: hard / L4 — Evaluating adequacy of management's remediation plan
(1, 'Misstatements and Control Deficiencies', 'After the prior-year audit of Summit Ridge Energy Corp., the auditor communicated a material weakness related to inadequate review of complex derivative valuations. In the current year, management asserts it has remediated the weakness by hiring a derivatives specialist and implementing a quarterly valuation review. However, the specialist reports to the CFO who previously approved the erroneous valuations, and the quarterly review was not performed in Q3. The auditor should:', '["Accept the remediation because management hired a specialist with appropriate expertise", "Conclude the material weakness has not been remediated because the organizational reporting structure and inconsistent operation undermine the control''s effectiveness", "Downgrade the finding to a significant deficiency because management has demonstrated good-faith remediation efforts", "Defer the evaluation until the specialist has completed a full annual cycle of quarterly reviews"]'::jsonb, 1, 'Under AU-C 265.A8-.A12, the auditor evaluates both the design and operation of remediated controls. The specialist reporting to the CFO who approved the original errors compromises review independence, and skipping Q3 demonstrates inconsistent operation. Choice A is incorrect because hiring qualified personnel alone does not remediate a material weakness—the control must be both properly designed with appropriate reporting lines and consistently operated throughout the period.', 'hard', 4),

-- Q22: easy / L1 — Definition of a control deficiency under AU-C 265
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, a control deficiency exists when:', '["An internal control fails to detect a material misstatement in the financial statements", "Management intentionally overrides an established internal control procedure", "A control is designed, implemented, or operated such that it is unable to prevent or detect misstatements on a timely basis", "The auditor identifies a deviation from an established control procedure during testing"]'::jsonb, 2, 'Under AU-C 265.07, a control deficiency exists when the design or operation of a control does not allow management or employees to prevent or detect misstatements on a timely basis. This encompasses both design and operating failures. Choice D is incorrect because a test deviation is evidence that may indicate a control deficiency, but the deficiency itself is defined by the control''s inability to prevent or detect misstatements—not by the testing result alone.', 'easy', 1),

-- Q23: hard / L4 — Assessing aggregation of deficiencies across multiple processes
(1, 'Misstatements and Control Deficiencies', 'During the audit of Pacific Rim Technologies Inc., the auditor identifies three control deficiencies: (1) the purchasing department does not match receiving reports to purchase orders before payment, (2) the IT department has not restricted access for terminated employees within 48 hours, and (3) month-end bank reconciliations are not independently reviewed. Individually, none rises to a significant deficiency. Which assessment approach is most appropriate for evaluating whether these deficiencies in combination constitute a significant deficiency or material weakness?', '["Evaluate each deficiency independently because they affect different transaction cycles and cannot be combined", "Combine the deficiencies only if they affect the same financial statement assertion", "Aggregate only the deficiencies related to the same process, such as the purchasing and IT access deficiencies", "Consider whether the deficiencies share a common root cause or collectively increase the likelihood that a material misstatement would not be prevented or detected"]'::jsonb, 3, 'Under AU-C 265.A10, the auditor considers whether deficiencies in combination constitute a significant deficiency or material weakness by evaluating common root causes—such as inadequate management oversight—and the collective effect on likelihood of undetected misstatements. Choice A is incorrect because AU-C 265 explicitly requires evaluating deficiencies in combination, even across different transaction cycles, when they may share underlying causes or collectively affect the control environment.', 'hard', 4),

-- Q24: medium / L2 — Iron curtain vs. rollover method for misstatement evaluation
(1, 'Misstatements and Control Deficiencies', 'During the audit of Keystone Building Materials Inc., the auditor evaluates a $30,000 overstatement of depreciation expense that originated two years ago. Using the rollover method, the current-year income statement effect is zero because the error did not recur. Using the iron curtain method, the balance sheet shows a cumulative $30,000 understatement of fixed assets. Materiality is $50,000. Under AU-C 450, the auditor should:', '["Consider both the rollover and iron curtain approaches and evaluate whether either method indicates a material misstatement", "Use only the rollover method because the current-year income statement is the primary focus", "Use only the iron curtain method because the balance sheet carries the cumulative effect", "Average the results of both methods to determine the net effect on the financial statements"]'::jsonb, 0, 'Under AU-C 450.A16, the auditor should consider both the income statement effect (rollover method) and the balance sheet effect (iron curtain method) when evaluating uncorrected misstatements from prior periods. Neither method alone provides a complete picture. Choice B is incorrect because relying solely on the rollover method would ignore the cumulative $30,000 balance sheet understatement, which could be material when combined with other uncorrected misstatements.', 'medium', 2),

-- Q25: easy / L1 — Definition of a misstatement under AU-C 450
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, which of the following is included in the definition of a misstatement?', '["Only errors in recorded monetary amounts on the face of the financial statements", "Differences between the amount, classification, presentation, or disclosure of a reported item and what is required by the applicable financial reporting framework", "Only intentional manipulations of financial data by management or employees", "Only quantitative errors that exceed the overall materiality threshold"]'::jsonb, 1, 'Under AU-C 450.04, a misstatement is defined broadly to include differences in amount, classification, presentation, or disclosure relative to the requirements of the applicable financial reporting framework. This encompasses errors in footnotes, classification, and presentation. Choice A is incorrect because misstatements extend beyond face-of-statement monetary amounts to include classification errors, incomplete disclosures, and presentation deficiencies.', 'easy', 1),

-- Q26: medium / L3 — Analyzing effect of prior-year misstatements on opening balances for initial engagement
(1, 'Misstatements and Control Deficiencies', 'An auditor is engaged to audit Copperfield Holdings Inc. for the first time. The prior auditor identified $55,000 in uncorrected misstatements in the prior year but issued an unmodified opinion. Current-year materiality is $80,000. The auditor determines that $40,000 of the prior-year misstatements affect the current-year opening balances. What is the most likely effect on the current-year audit?', '["The auditor should disclaim an opinion because the prior-year uncorrected misstatements create a scope limitation", "The auditor should require management to restate the prior-year financial statements before beginning current-year fieldwork", "The auditor should include the $40,000 in the current-year evaluation of uncorrected misstatements and assess the combined effect with any current-year misstatements", "The auditor should disregard the prior-year misstatements because the predecessor auditor already evaluated their effect"]'::jsonb, 2, 'Under AU-C 510.10 and AU-C 450.10, when prior-period uncorrected misstatements affect opening balances, the current-year auditor must evaluate their effect on the current-year financial statements. The $40,000 must be included when assessing aggregate uncorrected misstatements against current-year materiality. Choice D is incorrect because the predecessor auditor''s evaluation does not relieve the successor—the current auditor must independently assess the effect of prior misstatements on the current period.', 'medium', 3),

-- Q27: medium / L2 — Communicating previously communicated deficiencies in current year
(1, 'Misstatements and Control Deficiencies', 'During the current-year audit of Riverdale Manufacturing Corp., the auditor identifies the same material weakness in inventory valuation that was communicated to those charged with governance in the prior year. Management has not yet remediated the weakness. Under AU-C 265, the auditor should:', '["Communicate the material weakness again in writing in the current year, noting that it was previously communicated", "Refrain from communicating the weakness again because it was already reported in the prior year", "Downgrade the finding to a significant deficiency if no actual misstatements resulted from it this year", "Communicate the weakness only if the amount of potential misstatement has increased since the prior year"]'::jsonb, 0, 'Under AU-C 265.A18, the auditor is required to communicate significant deficiencies and material weaknesses in writing each year they are identified, even if previously communicated. Repeat communication alerts governance that remediation has not occurred. Choice B is incorrect because AU-C 265 does not exempt previously reported deficiencies from current-year communication—the annual requirement applies regardless of whether the deficiency was reported before.', 'medium', 2),

-- Q28: easy / L1 — Who receives communications about lesser control deficiencies
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, to whom may the auditor communicate control deficiencies that are not significant deficiencies or material weaknesses?', '["Only to the audit committee in a formal written report", "Only to the entity''s external legal counsel", "Only to regulatory authorities overseeing the entity", "To management at an appropriate level of responsibility"]'::jsonb, 3, 'Under AU-C 265.12, the auditor may communicate control deficiencies that are not significant deficiencies or material weaknesses to management at an appropriate level of responsibility. This communication may be written or oral. Choice A is incorrect because the requirement to communicate in writing to those charged with governance applies only to significant deficiencies and material weaknesses—lesser deficiencies are communicated to management, not necessarily the audit committee.', 'easy', 1),

-- Q29: medium / L3 — Analyzing effect of routine management override on control environment
(1, 'Misstatements and Control Deficiencies', 'While auditing Crestline Financial Services, the auditor discovers that the CFO routinely bypasses the automated three-way matching control in the accounts payable system to expedite vendor payments. The CFO''s manual approvals are documented but not reviewed by anyone else. No misstatements have been detected. What is the most likely effect on the auditor''s evaluation of this control environment?', '["The CFO''s documentation of manual approvals constitutes a sufficient compensating control", "The deficiency is mitigated because no misstatements have occurred, indicating the override is low-risk", "The routine override weakens the control environment and increases the risk that misstatements could occur without detection, warranting classification as at least a significant deficiency", "The override has no effect on the control environment because it involves an authorized officer"]'::jsonb, 2, 'Under AU-C 265.A7 and AU-C 315.A83, routine management override of designed controls—even when documented—undermines the control environment because it removes a preventive safeguard without adequate compensating review. The unreviewed nature of the approvals eliminates the detective element. Choice D is incorrect because authorization of an officer to override a control does not eliminate the deficiency—the control environment depends on controls operating as designed, and systematic override without independent review creates a gap.', 'medium', 3),

-- Q30: easy / L1 — Auditor's documentation requirements for misstatements
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, which of the following must the auditor document regarding misstatements identified during the audit?', '["Only the misstatements that exceed the clearly trivial threshold and remain uncorrected", "The amount below which misstatements are regarded as clearly trivial, all accumulated misstatements, and whether they have been corrected", "Only the misstatements that management has agreed to correct", "Only the aggregate total of all misstatements without individual detail"]'::jsonb, 1, 'Under AU-C 450.14, the auditor must document the clearly trivial threshold, all misstatements accumulated during the audit, whether those misstatements were corrected, and the conclusion on whether uncorrected misstatements are material. Choice A is incorrect because documentation also includes the clearly trivial threshold itself and corrected misstatements—not only uncorrected items above the threshold.', 'easy', 1)
;

COMMIT;
